export interface Member {
  email: string;
  role: string;
  lastSeen: string | null;
}

export interface MemberPage {
  items: Member[];
  page: number;
  pageSize: number;
  pages: number;
  total: number;
}

export function selectMembers(
  members: readonly Member[],
  query: string,
  page: number,
  pageSize: number,
): MemberPage {
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(pageSize) || pageSize <= 0) {
    throw new RangeError('Invalid pagination');
  }
  const needle = query.trim().toLowerCase();
  const filtered = members.filter(member => member.email.toLowerCase().includes(needle));
  const pages = Math.ceil(filtered.length / pageSize);
  const selectedPage = pages === 0 ? 0 : Math.min(page, pages);
  const start = selectedPage * pageSize;
  return {
    items: filtered.slice(start, start + pageSize).map(member => ({ ...member })),
    page: selectedPage,
    pageSize,
    pages,
    total: filtered.length,
  };
}
```

