import { selectMembers, type Member } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function rangeError(page: number, pageSize: number): void {
  try {
    selectMembers([], '', page, pageSize);
  } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error('expected RangeError');
  }
  throw new Error('expected RangeError');
}

const members: readonly Member[] = [
  { email: 'Alpha@Example.com', role: 'admin', lastSeen: '2025-01-01' },
  { email: 'beta@example.com', role: 'member', lastSeen: null },
  { email: 'ALPHABET@example.org', role: 'viewer', lastSeen: '2025-02-01' },
  { email: 'other@example.com', role: 'member', lastSeen: null },
  { email: 'Kelvin@example.com', role: 'special', lastSeen: null },
  { email: 'Kelvin@example.com', role: 'ascii', lastSeen: null },
];
const snapshot = JSON.stringify(members);
const first = selectMembers(members, '  aLpHa  ', 0, 1);
equal(first, { items: [members[0]], page: 0, pageSize: 1, pages: 2, total: 2 }, 'filter and first page');
assert(first.items[0] !== members[0], 'returned member must be copied');
const clamped = selectMembers(members, 'alpha', 99, 1);
equal(clamped, { items: [members[2]], page: 1, pageSize: 1, pages: 2, total: 2 }, 'page clamps to last page');

const asciiOnly = selectMembers(members, 'kELVIN', 0, 10);
equal(asciiOnly.items.map(item => item.role), ['ascii'], 'case folding is ASCII-style only');
equal(asciiOnly.total, 1, 'ASCII filtering total');

const all = selectMembers(members, '   ', 1, 4);
equal(all.items, [members[4], members[5]], 'blank query and source order');
equal({ page: all.page, pages: all.pages, total: all.total }, { page: 1, pages: 2, total: 6 }, 'total before pagination');
const none = selectMembers(members, 'not-present', 50, 3);
equal(none, { items: [], page: 0, pageSize: 3, pages: 0, total: 0 }, 'no-result pagination');
assert(JSON.stringify(members) === snapshot, 'input must not mutate');

rangeError(-1, 1);
rangeError(0.5, 1);
rangeError(Number.NaN, 1);
rangeError(0, 0);
rangeError(0, -2);
rangeError(0, 1.5);

